'use client';

import { styled } from '@mui/material/styles';

// ----------------------------------------------------------------------

const LoaderRoot = styled('div')(({ theme }) => ({
  '--size': '250px',
  '--duration': '2s',
  '--logo-color':
    theme.palette.mode === 'dark' ? 'rgba(150, 150, 150, 1)' : 'rgba(100, 100, 100, 1)',
  '--background': `linear-gradient(
    0deg,
    ${theme.palette.mode === 'dark' ? 'rgba(80, 80, 80, 0.2)' : 'rgba(50, 50, 50, 0.2)'} 0%,
    ${theme.palette.mode === 'dark' ? 'rgba(130, 130, 130, 0.2)' : 'rgba(100, 100, 100, 0.2)'} 100%
  )`,
  height: 'var(--size)',
  aspectRatio: 1,
  position: 'relative',

  '@keyframes ripple': {
    '0%': {
      transform: 'scale(1)',
      boxShadow: 'rgba(0, 0, 0, 0.3) 0px 10px 10px -0px',
    },
    '50%': {
      transform: 'scale(1.3)',
      boxShadow: 'rgba(0, 0, 0, 0.3) 0px 30px 20px -0px',
    },
    '100%': {
      transform: 'scale(1)',
      boxShadow: 'rgba(0, 0, 0, 0.3) 0px 10px 10px -0px',
    },
  },

  '@keyframes color-change': {
    '0%': {
      fill: 'var(--logo-color)',
    },
    '50%': {
      fill: theme.palette.primary.main,
    },
    '100%': {
      fill: 'var(--logo-color)',
    },
  },
}));

const Box = styled('div')(({ theme }) => ({
  position: 'absolute',
  background: 'var(--background)',
  borderRadius: '50%',
  borderTop: `1px solid ${theme.palette.mode === 'dark' ? 'rgba(150, 150, 150, 1)' : 'rgba(100, 100, 100, 1)'}`,
  boxShadow: 'rgba(0, 0, 0, 0.3) 0px 10px 10px -0px',
  backdropFilter: 'blur(5px)',
  animation: 'ripple var(--duration) infinite ease-in-out',

  '&:nth-of-type(1)': {
    inset: '40%',
    zIndex: 99,
  },
  '&:nth-of-type(2)': {
    inset: '30%',
    zIndex: 98,
    borderColor: 'rgba(100, 100, 100, 0.8)',
    animationDelay: '0.2s',
  },
  '&:nth-of-type(3)': {
    inset: '20%',
    zIndex: 97,
    borderColor: 'rgba(100, 100, 100, 0.6)',
    animationDelay: '0.4s',
  },
  '&:nth-of-type(4)': {
    inset: '10%',
    zIndex: 96,
    borderColor: 'rgba(100, 100, 100, 0.4)',
    animationDelay: '0.6s',
  },
  '&:nth-of-type(5)': {
    inset: '0%',
    zIndex: 95,
    borderColor: 'rgba(100, 100, 100, 0.2)',
    animationDelay: '0.8s',
  },
}));

const LogoWrapper = styled('div')({
  position: 'absolute',
  inset: 0,
  display: 'grid',
  placeContent: 'center',
  padding: '30%',
  zIndex: 100,
});

const LogoSvg = styled('svg')({
  fill: 'var(--logo-color)',
  width: '100%',
  animation: 'color-change var(--duration) infinite ease-in-out',
});

// ----------------------------------------------------------------------

